	/** 
	 * jumpstart the process by instantiating2 Building
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		buildingId = BuildingService.getBuildingInstance()
		.createBuilding( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		BuildingService.getBuildingInstance()
				.createBuilding( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.buildingSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Building : " + successValue.getBuildingId());
							  if (successValue.getBuildingId().equals(buildingId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfBuildingList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Building test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on building consumed")
					);
			subscriber.buildingSubscribe( buildingId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Building : " + successValue.getBuildingId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfBuildingList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on building for buildingId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Building. 
	 */
	protected Building read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Building" );

		Building entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Building with primary key" );
		msg.append( buildingId );
		
		BuildingFetchOneSummary fetchOneSummary = new BuildingFetchOneSummary( buildingId );

		try {
			entity = BuildingService.getBuildingInstance().getBuilding( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Building " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Building.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Building." );

		StringBuilder msg = new StringBuilder( "Failed to update a Building : " );        
		Building entity = read();
		UpdateBuildingCommand command = generateUpdateCommand();
		command.setBuildingId(entity.getBuildingId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Building." );

			// for use later on...
			buildingId = entity.getBuildingId();

			BuildingService proxy = BuildingService.getBuildingInstance();  

			proxy.updateBuilding( command ).get();

			LOGGER.info( "-- Successfully saved Building - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + buildingId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Building.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Building." );

		Building entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Building with id " + buildingId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Building with id " + buildingId );

			throw e;
		}

		try{
			BuildingService.getBuildingInstance().delete( new DeleteBuildingCommand( entity.getBuildingId() ) ).get();
			LOGGER.info( "-- Successfully deleted Building with id " + buildingId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Building with id " + buildingId );

			throw e;
		}
	}

	/**
	 * get all Buildings.
	 */
	protected List<Building> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Buildings:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Building : " );        
		List<Building> collection  = new ArrayList<>();

		try {
			// call the static get method on the BuildingService
			collection = BuildingService.getBuildingInstance().getAllBuilding();
			assertNotNull( collection, "An Empty collection of Building was incorrectly returned.");
			
			// Now print out the values
			Building entity = null;            
			Iterator<Building> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getBuildingId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

